import json,re
d=json.load(open('.ai/task/repair-w57-20260930/CONTEXTUAL-ENVELOPE-f2a3.json'))
p=d['payload']
pat=re.compile(r'#\{[a-z]+\}#|#[A-Z_]+#|<\?.*?\?>|%[-+ #0]*\d*(?:\.\d+)?[sdfq%]|\[/?[a-z]+\]|\$\w+|@\w+@')
for i,t in enumerate(p['translation_snapshot']):
  s,tg=t['source'],t['target']
  from collections import Counter
  a=Counter(pat.findall(s)); b=Counter(pat.findall(tg))
  msgs=[]
  if a!=b: msgs.append(('tok',dict(a-b),dict(b-a)))
  if s.count('\n')!=tg.count('\n'): msgs.append(('lf',s.count('\n'),tg.count('\n')))
  sl=s.split('\n'); tl=tg.split('\n')
  if len(sl)==len(tl):
    eb=[j for j,(x,y) in enumerate(zip(sl,tl)) if (x.strip()=='')!=(y.strip()=='')]
    if eb: msgs.append(('blankpos',eb[:5]))
    lt=[j for j,(x,y) in enumerate(zip(sl,tl)) if re.match(r'[\t ]*',x).group()!=re.match(r'[\t ]*',y).group()]
    if lt: msgs.append(('lead',lt[:5]))
  if tg.strip()=='' : msgs.append('empty')
  if msgs: print(i,msgs)
